`timescale 1ns/1ps
module tb_fp32_mlo_merge8_candidate;
 logic clk,rst_n,hv,hr,bv,br,hov,hor,bov,bor,last_i,last_o,no_stall;logic[255:0]ma,la,mb,lb,mo,lo;logic[1023:0]oa,ob,oo;logic[31:0]lfsr;integer cycles,beats;
 always #0.5 clk=~clk;always_ff@(posedge clk)if(!rst_n)begin cycles<=0;lfsr<=32'h8a11ce;end else begin cycles<=cycles+1;lfsr<={lfsr[30:0],lfsr[31]^lfsr[21]^lfsr[1]^lfsr[0]};end
 fp32_mlo_merge8_candidate dut(.clk_i(clk),.rst_ni(rst_n),.header_valid_i(hv),.header_ready_o(hr),.ma_i(ma),.la_i(la),.mb_i(mb),.lb_i(lb),.beat_valid_i(bv),.beat_ready_o(br),.oa_i(oa),.ob_i(ob),.beat_last_i(last_i),.header_valid_o(hov),.header_ready_i(hor),.m_o(mo),.l_o(lo),.beat_valid_o(bov),.beat_ready_i(bor),.o_o(oo),.beat_last_o(last_o));
 initial begin clk=0;rst_n=0;hv=0;bv=0;hor=0;bor=0;last_i=0;beats=0;no_stall=$test$plusargs("NOSTALL");ma={8{32'hc06640f5}};la={8{32'h42281225}};mb={8{32'h401e816d}};lb={8{32'h435efd06}};oa={8{{32'hc18ef9ce,32'h41d4aa05,32'hc173e7c3,32'hc2739216}}};ob={8{{32'h42767f70,32'hc22d4652,32'hc23f4244,32'h41277666}}};repeat(6)@(posedge clk);rst_n=1;@(negedge clk);hv=1;do@(posedge clk);while(!hr);@(negedge clk);hv=0;while(!hov)@(posedge clk);if(mo!=={8{32'h401e816d}}||lo!=={8{32'h435f15c8}})$fatal(1,"header");@(negedge clk);hor=1;@(posedge clk);@(negedge clk);hor=0;for(integer beat=0;beat<32;beat++)begin bv=1;last_i=beat==31;do@(posedge clk);while(!br);@(negedge clk);bv=0;last_i=0;while(!bov)@(posedge clk);if(oo!=={8{{32'h42765552,32'hc22d07ac,32'hc23f6631,32'h41253860}}}||last_o!==(beat==31))$fatal(1,"beat=%0d",beat);bor=no_stall||(lfsr[0]||lfsr[5]);while(!bor)begin @(posedge clk);bor=no_stall||(lfsr[0]||lfsr[5]);end @(posedge clk);@(negedge clk);bor=0;beats++;end $display("MLO_MERGE8_CANDIDATE_PASS rows=8 beats=%0d cycles=%0d nominal=%0d",beats,cycles,no_stall);$finish;end
 initial begin repeat(10000)@(posedge clk);$fatal(1,"timeout");end
endmodule
